BEGIN;
DO $test$
DECLARE t uuid:=gen_random_uuid();u uuid:=gen_random_uuid();site uuid:=gen_random_uuid();art uuid:=gen_random_uuid();svc uuid:=gen_random_uuid();cust uuid:=gen_random_uuid();org uuid:=gen_random_uuid();conv uuid:=gen_random_uuid();ben uuid:=gen_random_uuid();sid uuid:=gen_random_uuid();iid uuid:=gen_random_uuid();l1 uuid:=gen_random_uuid();l2 uuid:=gen_random_uuid();ret uuid:=gen_random_uuid();ri uuid:=gen_random_uuid();bord uuid:=gen_random_uuid();r jsonb;items jsonb;allitems jsonb;
BEGIN
 INSERT INTO public.tenants(id,name,enabled_modules,settings) VALUES(t,'RECETTE VENTILATION RETOUR IPM','[]','{}');
 INSERT INTO auth.users(id,email,aud,role) VALUES(u,u::text||'@example.invalid','authenticated','authenticated');
 INSERT INTO public.profiles(id,tenant_id,role,site_access_mode,full_name,is_active) VALUES(u,t,'admin','all','Recette IPM',true);
 INSERT INTO public.sites(id,tenant_id,name,is_active) VALUES(site,t,'Pharmacie fictive',true);
 INSERT INTO public.customers(id,tenant_id,name) VALUES(cust,t,'Patient fictif');
 INSERT INTO public.articles(id,tenant_id,internal_ref,name,sale_price,track_stock,ipm_eligible) VALUES(art,t,'EL-154','Eligible',2000,true,true),(svc,t,'NE-154','Non éligible',2000,false,false);
 INSERT INTO public.ipm_organismes(id,tenant_id,nom) VALUES(org,t,'Organisme fictif');
 INSERT INTO public.ipm_conventions(id,tenant_id,organisme_id,nom,taux_defaut,mode_calcul,mode_arrondi) VALUES(conv,t,org,'Convention fictive',80,'articles_eligibles','round');
 INSERT INTO public.ipm_beneficiaires(id,tenant_id,customer_id,organisme_id,convention_id,matricule,statut) VALUES(ben,t,cust,org,conv,'REC-154','actif');
 INSERT INTO public.sales(id,tenant_id,site_id,user_id,customer_id,sale_number,subtotal,total,paid,status,source,vat_enabled_at_issue) VALUES(sid,t,site,u,cust,'IPM-REC-154',10000,10000,3600,'partial','billing',false);
 INSERT INTO public.sale_items(id,tenant_id,sale_id,article_id,name,quantity,unit_price,total,site_id) VALUES(l1,t,sid,art,'Eligible',4,2000,8000,site),(l2,t,sid,svc,'Non éligible',1,2000,2000,site);
 INSERT INTO public.ipm_ventes(id,tenant_id,organisme_id,beneficiaire_id,convention_id,sale_id,part_ipm,part_client,montant_total,taux_prise_en_charge,montant_eligible,montant_non_eligible,part_beneficiaire_payee) VALUES(iid,t,org,ben,conv,sid,6400,3600,10000,80,8000,2000,3600);
 PERFORM public._ipm_capture_new_sale_snapshot(t,sid,iid);
 UPDATE public.ipm_conventions SET taux_defaut=20 WHERE id=conv;
 UPDATE public.articles SET ipm_eligible=false WHERE id=art;
 items:=jsonb_build_array(jsonb_build_object('sale_item_id',l2,'quantity',1));
 allitems:=items||jsonb_build_array(jsonb_build_object('sale_item_id',l1,'quantity',4));
 PERFORM set_config('request.jwt.claim.sub',u::text,true);EXECUTE 'SET LOCAL ROLE authenticated';
 r:=public.inspect_ipm_return(sid,items);
 IF r->>'state' IS DISTINCT FROM 'non_bordereaute' OR r->>'split_exact' IS DISTINCT FROM 'true' OR (r->>'patient_return')::numeric<>2000 OR (r->>'ipm_return')::numeric<>0 THEN RAISE EXCEPTION 'Retour non éligible incorrect : %',r;END IF;
 r:=public.inspect_ipm_return(sid,allitems);
 IF (r->>'patient_return')::numeric<>3600 OR (r->>'ipm_return')::numeric<>6400 OR r->>'all_quantities_returned_after' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Retour total incorrect : %',r;END IF;
 EXECUTE 'RESET ROLE';
 -- Prior return is a synthetic proof fixture; this recipe does not execute a refund.
 INSERT INTO public.sale_returns(id,tenant_id,site_id,sale_id,customer_id,return_number,total,refund_method,status,restock) VALUES(ret,t,site,sid,cust,'RET-154',2000,'none','approved',false);
 INSERT INTO public.sale_return_items(id,tenant_id,return_id,sale_item_id,article_id,name,quantity,unit_price,total,purchase_cost) VALUES(ri,t,ret,l1,art,'Eligible',1,2000,2000,0);
 EXECUTE 'SET LOCAL ROLE authenticated';
 r:=public.inspect_ipm_return(sid,items);
 IF r->>'state' IS DISTINCT FROM 'historique_a_rapprocher' OR r->>'split_exact' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'Retour ancien non documenté accepté : %',r;END IF;
 EXECUTE 'RESET ROLE';
 INSERT INTO public.ipm_return_line_snapshots(tenant_id,sale_id,sale_item_id,return_id,return_item_id,prior_quantity,quantity,ipm_amount,patient_amount) VALUES(t,sid,l1,ret,ri,0,1,1600,400);
 allitems:=items||jsonb_build_array(jsonb_build_object('sale_item_id',l1,'quantity',1),jsonb_build_object('sale_item_id',l1,'quantity',2));
 EXECUTE 'SET LOCAL ROLE authenticated';
 r:=public.inspect_ipm_return(sid,allitems);
 IF r->>'split_exact' IS DISTINCT FROM 'true' OR (r->>'ipm_return')::numeric<>4800 OR (r->>'patient_return')::numeric<>3200 OR (r->>'remaining_ipm_after')::numeric<>0 OR (r->>'remaining_patient_after')::numeric<>0 OR r->>'all_quantities_returned_after' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Retours cumulés incorrects : %',r;END IF;
 BEGIN PERFORM public.inspect_ipm_return(sid,jsonb_build_array(jsonb_build_object('sale_item_id',l1,'quantity',4)));RAISE EXCEPTION 'Sur-retour accepté';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM 1 FROM public.ipm_return_line_snapshots;RAISE EXCEPTION 'Historique des retours exposé';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 EXECUTE 'RESET ROLE';
 INSERT INTO public.ipm_bordereaux(id,tenant_id,organisme_id,numero,periode_debut,periode_fin,total_part_ipm,nombre_factures,statut) VALUES(bord,t,org,'BOR-154',current_date,current_date,6400,1,'brouillon');
 UPDATE public.ipm_ventes SET bordereau_id=bord WHERE id=iid;
 EXECUTE 'SET LOCAL ROLE authenticated';
 r:=public.inspect_ipm_return(sid,items);
 IF r->>'state' IS DISTINCT FROM 'bordereau_brouillon' OR r->>'split_exact' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Bordereau brouillon non détecté';END IF;
 EXECUTE 'RESET ROLE';
 UPDATE public.ipm_bordereaux SET statut='envoye' WHERE id=bord;
 EXECUTE 'SET LOCAL ROLE authenticated';
 r:=public.inspect_ipm_return(sid,items);
 IF r->>'state' IS DISTINCT FROM 'regularisation_document_emis' OR (r->>'patient_return')::numeric<>2000 THEN RAISE EXCEPTION 'Bordereau envoyé non protégé';END IF;
 EXECUTE 'RESET ROLE';
 IF (SELECT count(*) FROM public.sale_returns WHERE tenant_id=t)<>1 OR (SELECT count(*) FROM public.ipm_return_line_snapshots WHERE tenant_id=t)<>1 OR (SELECT part_ipm FROM public.ipm_ventes WHERE id=iid)<>6400 OR EXISTS(SELECT 1 FROM public.stock_movements WHERE tenant_id=t) OR EXISTS(SELECT 1 FROM public.sale_payments WHERE tenant_id=t) THEN RAISE EXCEPTION 'Diagnostic a modifié des opérations';END IF;
 IF has_function_privilege('authenticated','public._ipm_exact_return_plan(uuid,uuid,jsonb)','EXECUTE') OR has_function_privilege('authenticated','public._inspect_ipm_return_historical(uuid,jsonb)','EXECUTE') THEN RAISE EXCEPTION 'Primitives privées exposées';END IF;
END $test$;
ROLLBACK;
SELECT 'VENTILATION_RETOUR_IPM_OK' AS resultat;
